/* Decisions, persistence and responsive reading; no production writes. */
'use strict';
const {chromium,webkit,expect}=require('@playwright/test');
const assert=require('node:assert/strict'),fs=require('node:fs');
const engine=process.env.HLLV_BROWSER_ENGINE||'chromium';
const base=process.env.HLLV_TEST_URL||'http://127.0.0.1:8765/';
const output='artifacts/review-preview-qa';
let failurePage;
(async()=>{
  fs.mkdirSync(output,{recursive:true});
  const browser=await ({chromium,webkit}[engine]).launch();
  const context=await browser.newContext({viewport:{width:1440,height:900},acceptDownloads:true});
  const requests=[],errors=[];
  await context.route('**/*',route=>{
    const req=route.request();requests.push({method:req.method(),url:req.url()});
    if(req.method()!=='GET'||new URL(req.url()).origin!==new URL(base).origin)return route.abort();
    return route.continue();
  });
  const page=await context.newPage();failurePage=page;page.on('pageerror',e=>errors.push(String(e)));
  const button=name=>page.getByRole('button',{name,exact:true});
  await page.goto(new URL('review-preview.html',base).href,{waitUntil:'networkidle'});
  await expect(page.locator('#reviewProgress')).toContainText('6 awaiting review');
  await expect(page.locator('.rp-notice')).toContainText('do not publish');
  await expect(page.locator('#proposalStatus')).toHaveValue('shipped');
  await button('Approve example').click();
  await expect(page.locator('.rp-decision')).toHaveText('Approved in preview');
  await page.reload({waitUntil:'networkidle'});
  await expect(page.locator('.rp-decision')).toHaveText('Approved in preview');
  await expect(page.locator('#reviewProgress')).toContainText('5 awaiting review');
  await button('Reopen example').click();
  await page.locator('#proposalSummary').fill('Voice-volume slider fix released in Patch 1.7; independent gameplay verification pending.');
  await button('Save draft').click();
  await page.reload({waitUntil:'networkidle'});
  await expect(page.locator('#proposalSummary')).toHaveValue('Voice-volume slider fix released in Patch 1.7; independent gameplay verification pending.');
  await button('Reject example').click();
  await expect(page.locator('#formError')).toContainText('Add a reviewer note');
  await expect(page.locator('#reviewerNote')).toBeFocused();
  await page.locator('#reviewerNote').fill('Practice rejection to check retained evidence and history.');
  await button('Reject example').click();
  await expect(page.locator('.rp-decision')).toHaveText('Rejected in preview');
  await page.locator('.rp-audit>summary').click();
  await expect(page.locator('.rp-audit')).toContainText('Approved in preview');
  await expect(page.locator('.rp-audit')).toContainText('Reopened for review');
  await expect(page.locator('.rp-audit')).toContainText('Draft saved');
  await page.locator('[data-item="HLLV-102"]').click();
  await expect(page.locator('#proposalStatus')).toHaveValue('partial');
  await page.locator('#proposalStatus').selectOption('shipped');
  await button('Approve example').click();
  await expect(page.locator('#formError')).toContainText('Explain why');
  await page.locator('#proposalStatus').selectOption('partial');
  await button('Approve example').click();
  await page.locator('[data-item="HLLV-033"]').click();
  await expect(page.locator('#proposalStatus')).toHaveValue('investigating');
  await page.locator('[data-item="HLLV-F028"]').click();
  await expect(page.locator('#proposalStatus')).toHaveValue('planned');
  await expect(page.locator('.rp-target')).toContainText('November 2026 target');
  await page.locator('#reviewFilter').selectOption('pending');
  await button('Approve example').click();
  await expect(page.locator('#reviewDetail h2')).toHaveText('Running boat engines prevent spawning');
  await page.locator('#reviewFilter').selectOption('rejected');
  await expect(page.locator('#reviewDetail h2')).toHaveText('Voice volume stays excessively loud');
  await button('Reopen example').click();
  await expect(page.locator('#reviewDetail')).toContainText('No examples in this view');
  await page.locator('#reviewFilter').selectOption('all');
  const downloading=page.waitForEvent('download');await button('Export practice review').click();
  const download=await downloading,exportPath=`${output}/${engine}-practice-review.json`;
  await download.saveAs(exportPath);
  const exported=JSON.parse(fs.readFileSync(exportPath));
  assert.equal(exported.preview_only,true);assert.equal(exported.publishes_records,false);
  assert(exported.items.find(x=>x.id==='HLLV-061').practice_review.history.length>=5);
  const screenshots=[];
  for(const theme of ['dark','light'])for(const viewport of [{width:320,height:740},{width:390,height:844},{width:1440,height:900},{width:2560,height:1440}]){
    await page.setViewportSize(viewport);
    // Opening-layout checks load at the target viewport, independently of prior focus.
    const resized=await page.evaluate(()=>({viewport:innerWidth,scroll:document.documentElement.scrollWidth}));
    if(resized.scroll>resized.viewport+1)console.log('RESIZE_SCROLL_EXTENT',engine,JSON.stringify(resized));
    await page.reload({waitUntil:'networkidle'});
    await expect(page.locator('#reviewDetail h2')).toBeVisible();
    if(await page.locator('html').getAttribute('data-theme')!==theme)await page.locator('#themeToggle').click();
    await page.evaluate(()=>scrollTo(0,0));
    const overflow=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,elements:[...document.querySelectorAll('body *')].filter(el=>el.getBoundingClientRect().right>innerWidth+1).map(el=>({tag:el.tagName,id:el.id,cls:el.className,right:el.getBoundingClientRect().right,display:getComputedStyle(el).display})).slice(0,20)}));
    if(overflow.scroll>overflow.width+1)console.log('OVERFLOW_ISOLATION',JSON.stringify(await page.evaluate(async()=>{
      const result=[];
      for(const selector of ['.rp-skip','.site-nav','.site-backdrop','.rp-heading','.rp-notice','#previewMessage','.rp-toolbar','.rp-queue','.rp-mobile-picker','.rp-before','.rp-proposed','.rp-evidence','.rp-note','.rp-actions','.rp-audit','.rp-footer']){
        const el=document.querySelector(selector),prior=el.getAttribute('style');
        el.style.setProperty('display','none','important');await new Promise(requestAnimationFrame);
        result.push({selector,without:document.documentElement.scrollWidth});
        if(prior===null)el.removeAttribute('style');else el.setAttribute('style',prior);
        await new Promise(requestAnimationFrame);
      }
      return result;
    })));
    assert(overflow.scroll<=overflow.width+1,`${theme} ${viewport.width}: horizontal overflow ${JSON.stringify(overflow)}`);
    const title=await page.locator('#reviewDetail h2').boundingBox();
    assert(title.y+title.height<viewport.height,`${theme} ${viewport.width}: first example title below first view`);
    const file=`${output}/${engine}-${viewport.width}-${theme}.png`;
    await page.screenshot({path:file,fullPage:true});screenshots.push(file);
  }
  await page.setViewportSize({width:390,height:844});
  await page.locator('#reviewPicker').selectOption('HLLV-F017');
  await expect(page.locator('#reviewDetail h2')).toHaveText('M1A1 Thompson');
  await button('Approve example').click();
  await expect(page.locator('.rp-decision')).toHaveText('Approved in preview');
  const isolated=await browser.newContext({viewport:{width:1440,height:900}});
  await isolated.route('**/*',route=>new URL(route.request().url()).origin===new URL(base).origin&&route.request().method()==='GET'?route.continue():route.abort());
  await isolated.addInitScript(()=>{Storage.prototype.setItem=()=>{throw Error('Storage unavailable');};});
  const blocked=await isolated.newPage();await blocked.goto(new URL('review-preview.html',base).href);
  await blocked.getByRole('button',{name:'Approve example',exact:true}).click();
  await expect(blocked.locator('#previewMessage')).toContainText('this session only');
  assert.equal(requests.filter(r=>r.method!=='GET').length,0);
  assert.equal(requests.filter(r=>new URL(r.url).origin!==new URL(base).origin).length,0);
  assert.deepEqual(errors,[]);
  fs.writeFileSync(`${output}/${engine}-report.json`,JSON.stringify({engine,passed:true,screenshots,networkWrites:0,externalRequests:0},null,2));
  await browser.close();console.log('REVIEW_PREVIEW_PASS',engine);
})().catch(async error=>{
  console.error(error);
  await failurePage?.screenshot({path:`${output}/${engine}-failure.png`,fullPage:true}).catch(()=>{});
  process.exit(1);
});
